// We use the Verus verifier
use vstd::prelude::*;

verus! {

    /// Given a vector of complex numbers represented as (real, imag),
    /// returns a vector of the imaginary parts in the same order.
    ///
    /// Specifications:
    /// 1. The result has the same length as the input.
    /// 2. For every valid index i, result[i] == val[i].1.
    /// 3. If the imaginary part val[i].1 is 0.0, then result[i] == 0.0.
    /// 4. If val[i] is not the zero complex number, then result[i] == val[i].1.
    pub fn imag(val: Vec<(f64, f64)>) -> Vec<f64> {
        // No preconditions on the input
        ensures result.len() == val.len();
        ensures forall|i: usize| i < val.len() ==> result[i] == val[i].1;
        ensures forall|i: usize| i < val.len() && val[i].1 == 0.0
            ==> result[i] == 0.0;
        ensures forall|i: usize| i < val.len() && (val[i].0 != 0.0 || val[i].1 != 0.0)
            ==> result[i] == val[i].1;
        {
            // Build up the result by pushing each imaginary part
            let mut result: Vec<f64> = Vec::new();

            // We'll iterate with index `i` from 0 up to val.len()
            let mut i: usize = 0;
            while i < val.len() {
                // Loop invariants to support the proof
                invariant  i <= val.len();
                invariant  result.len() == i;
                invariant  forall|j: usize| j < i ==> result[j] == val[j].1;
                decreases val.len() - i;

                // Extract the i-th complex number (copying is OK since f64 is Copy)
                let (_re, im) = val[i];
                // Push the imaginary part onto our result
                result.push(im);
                // Advance
                i += 1;
            }

            result
        }
    }

}